/* Connect the recommendation rules to existing workspace actions and forms. */
const R=window.UniifyRecommendations;
let managerUpdating=false;
const managerSave=save;
save=function(message){if(!managerUpdating){managerUpdating=true;const changes=R.reconcile(state,new Date().toISOString());if(changes.length)adapt('Career recommendations updated from your assessment, goal and available resources');managerUpdating=false;}managerSave(message)};
proposed=function(){return R.suggest(state)};
applyPlan=function(){const changes=R.reconcile(state,new Date().toISOString());adapt('Career recommendations reviewed');save(changes.length?'Recommendations updated.':'Your recommendations are current.');closeDialog();location.hash='roadmap';render()};
const managerAssessment=assessment;
assessment=function(){let html=managerAssessment();const p=state.profile;return html.replace('<div class="panel-head"><h2>Your foundations check</h2>',`<div class="fields manager-context">${select('Career stage','context_stage',['Just starting','Released music, building an audience','Growing my career','Established independent artist'],p.stage)}${select('Primary goal','context_goal',['Release my first music','Grow my audience','Earn more from music','Improve career management','Find collaborators and opportunities'],p.goal)}${select('Current challenge','context_challenge',['Knowing what to do next','Budget and resources','Marketing and audience growth','Managing releases and tasks','Industry connections'],p.challenge)}${select('Hours each week','context_hours',['1–3 hours','4–7 hours','8–15 hours','16+ hours'],p.hours)}${field('Released tracks','context_tracks',p.tracks,'number','min="0" max="100000" step="1"')}${field('Monthly music budget','context_budget',p.budget,'number','min="0" max="100000000" step="0.01"')}${select('Currency','context_currency',['GBP','NGN','USD','EUR'],p.currency||'GBP')}<label class="field full"><span>Strengths</span><textarea name="context_strengths" maxlength="1500">${esc(p.strengths||'')}</textarea></label><label class="field full"><span>Current obstacles</span><textarea name="context_obstacles" maxlength="1500">${esc(p.obstacles||'')}</textarea></label></div><p class="small-copy muted">Blank answers remain unknown. <a href="#career">Record platform-specific audience observations in Career Progress.</a></p><div class="panel-head"><h2>Your foundations check</h2>`)};
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='assessment-form'){const data=Object.fromEntries(new FormData(f));if((state.entries.length||state.releases.some(r=>Number(r.budget)>0))&&data.context_currency!==(state.profile.currency||'GBP')){e.preventDefault();e.stopImmediatePropagation();toast('Keep the current currency while financial records exist.');return;}for(const [k,v]of Object.entries(data))if(k.startsWith('context_'))state.profile[k.slice(8)]=v;}
 if(f.id==='manager-checkin'){e.preventDefault();e.stopImmediatePropagation();const data=Object.fromEntries(new FormData(f));state.checkins||=[];state.checkins.push({id:uid(),date:today(),time:new Date().toISOString(),completed:data.completed,obstacle:data.obstacle});state.profile.obstacles=data.obstacle;if(data.hours)state.profile.hours=data.hours;record('checkin_completed','checkin','Weekly career review completed');save('Check-in saved. Recommendations reviewed.');closeDialog();render();}
},true);
const managerOverview=overview;
overview=function(){const next=activeTasks().filter(t=>!['Done','Deferred'].includes(t.status)&&!E.blocked(state,t)).sort((a,b)=>(b.priority||0)-(a.priority||0)||(a.order||0)-(b.order||0)).slice(0,3);const last=state.checkins?.at(-1);const due=!last||E.shift(last.date,7)<=today();return managerOverview()+`<section class="panel manager-next"><div class="panel-head"><h2>Recommended next actions</h2>${link('Career assessment','assessment')}</div>${next.length?next.map(t=>`<article class="manager-action"><h3><button class="text-link" data-task="${t.id}">${esc(t.title)}</button></h3><p>${esc(t.reason||'An action in your career plan.')}</p><small>${t.effort||t.minutes||30} minutes · ${esc(t.releaseId?state.releases.find(r=>r.id===t.releaseId)?.title||'Release':'General career work')}</small></article>`).join(''):'<p>Complete your assessment or create a release to choose your next steps.</p>'}</section><section class="panel manager-next"><div class="panel-head"><h2>Weekly check-in</h2><button class="text-link" data-manager-checkin>Review your week</button></div><p>${due?'Your review is due. Record what moved forward and what got in the way.':'Last reviewed '+date(last.date)+'. Next review '+date(E.shift(last.date,7))+'.'}</p></section>`};
const managerNotice=scheduleNotice;scheduleNotice=function(){const history=state.recommendationHistory?.at(-1);return managerNotice()+(history?`<details class="panel"><summary>Recommendation changes · ${date(history.time.slice(0,10))}</summary><ul>${history.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="small-copy muted">Based on your saved inputs using planning rules. Undo above restores automatic scheduling changes only.</p></details>`:'')};
const managerSettings=settings;settings=function(){if(!window.uniifyCloud)return managerSettings();return header('Settings & data')+`<section class="panel"><h2>Private cloud workspace</h2><p>Your records sync to your account. Pending changes are retained on this device when a save fails. The save status is shown in the header.</p><div class="form-actions">${btn('Export workspace','export','download')}<button class="text-link" data-cloud-retry>Retry save</button></div></section>`};
const managerProfile=profile;profile=function(){return managerProfile().replace('Saved only in this browser.',window.uniifyCloud?'Saved to your private cloud workspace.':'Saved on this device.')};
document.addEventListener('click',e=>{if(e.target.closest('[data-manager-checkin]'))openDialog('Weekly check-in',`<form id="manager-checkin"><div class="fields"><label class="field full"><span>What moved forward?</span><textarea name="completed" maxlength="2000" required></textarea></label><label class="field full"><span>What got in the way?</span><textarea name="obstacle" maxlength="2000"></textarea></label>${select('Hours next week','hours',['1–3 hours','4–7 hours','8–15 hours','16+ hours'],state.profile.hours)}</div><button class="theme-btn-two">Save check-in</button></form>`);if(e.target.closest('[data-cloud-retry]'))window.uniifyCloud?.flush();});
if(!state.history.length&&!state.releases.length&&!location.hash)location.hash='assessment';
save();render();
